/*
 * A321102  Sequence generated by: a(3*n) = 1, a(3*n+2) = 1 - a(3*n+1),
 *          a(9*n+1) = 1, a(9*n+7) = 0, a(9*n+4) = 1 - a(3*n+1), for n >= 0.
 * https://oeis.org/A321102
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(3*n) = 2, a(3*n+2) = 1 - a(3*n+1), a(9*n+1) = 1, a(9*n+7) = 0,
 *            a(9*n+4) = 1 - a(3*n+1)
 * Range:     u8 n <= 200, u16 n <= 200, u32 n <= 200, u64 n <= 200,
 *            u128 n <= 200, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    static seq_t *cache = NULL;
    static idx_t cache_size = 0;

    if (n >= cache_size) {
        /* Allocate new cache large enough up to n */
        idx_t new_size = n + 1;
        seq_t *new_cache = (seq_t *)malloc(new_size * sizeof(seq_t));
        /* Copy old contents if any */
        if (cache) {
            for (idx_t i = 0; i < cache_size; ++i)
                new_cache[i] = cache[i];
            free(cache);
        }
        cache = new_cache;

        /* Compute new entries */
        for (idx_t i = cache_size; i <= n; ++i) {
            if (i % 3 == 0) {
                cache[i] = 2;
            } else if (i % 9 == 1) {
                cache[i] = 1;
            } else if (i % 9 == 7) {
                cache[i] = 0;
            } else if (i % 3 == 1) {           /* i % 9 == 4 */
                idx_t idx = 3 * (i / 9) + 1;
                cache[i] = 1 - cache[idx];
            } else { /* i % 3 == 2 */
                cache[i] = 1 - cache[i - 1];
            }
        }
        cache_size = n + 1;
    }
    return cache[n];
}
